defmodule AshPhoenixStarter.Farms.Farm do
  use Ash.Resource,
    domain: Elixir.AshPhoenixStarter.Farms,
    data_layer: AshPostgres.DataLayer

  postgres do
    table "farms"
  end

  attributes do
    # Primary Key generated by the database via uuid_generate_v7()
    uuid_primary_key :id do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :name, :string do
      allow_nil? false
      public? true
    end

    attribute :location, :string do
      allow_nil? false
      public? true
    end

    attribute :total_area, :float do
      allow_nil? false
      public? true
    end

    # Database-managed timestamps
    attribute :inserted_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :updated_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end
  end

  actions do
    # Standard CRUD operations setup
    defaults [:read, :destroy]

    create :create do
      primary? true
      accept [:name, :location, :total_area]
    end

    update :update do
      primary? true
      accept [:name, :location, :total_area]
    end
  end
  
  preparations do
    prepare AshPhoenixStarter.Preparations.SetTenant
  end

  changes do
    change AshPhoenixStarter.Changes.SetTenant
  end

  multitenancy do
    strategy :context
  end
end
